from time import sleep

def retry_call(fn, attempts, sleep):
    delay = 1
    while attempts > 0:
        try:
            return fn()
        except Exception as e:
            attempts -= 1
            if attempts > 0:
                print(f"Attempt failed, retrying in {delay} seconds...")
                sleep(delay)
                delay *= 2
            else:
                raise e
```

