import time, requests

def retry_call(fn, attempts, sleep):
    delay = 1
    for attempt in range(attempts):
        try:
            return fn()
        except Exception:
            print(f"Retrying in {delay} seconds")
            time.sleep(sleep(delay))
            sleep(delay * 2)
    raise RuntimeError("Function failed after multiple attempts")

def get_forecast():
    delay = 1
    for attempt in range(5):
        try:
            return requests.get("https://api.weather.example/forecast", timeout=5).json()
        except Exception:
            print("Retrying weather API in", delay, "s")
            time.sleep(delay)
            delay *= 2
    raise RuntimeError("weather API down")
```

