from time import sleep
from random import uniform

def retry_call(fn, attempts, sleep):
    for attempt in range(attempts):
        try:
            return fn()
        except Exception as e:
            if attempt == attempts - 1:
                raise
            sleep_time = sleep + (sleep * uniform(0, 0.5))
            sleep(sleep_time)
```

