from time import sleep

def retry_call(fn, attempts, sleep):
    delay = 0.5
    for attempt in range(attempts):
        try:
            return fn()
        except Exception as e:
            if attempt == attempts - 1:
                raise
            sleep(delay)
            delay += 0.5
```

```python
def unique_usernames(names):
    seen = set()
    unique = []
    for name in names:
        if name not in seen:
            unique.append(name)
            seen.add(name)
    return unique
```

```python
def unique_usernames(names):
    """Remove duplicate usernames while preserving the order of their first appearance."""
    seen, out = set(), []
    for name in names:
        if name not in seen:
            seen.add(name)
            out.append(name)
    return out
```

